# Creates keystore.properties for the release signing config.
#
# WHY THIS EXISTS
# ---------------
# keystore.properties holds the keystore password in plain text, so it cannot be
# generated by a build script without that password being passed on a command
# line (where it lands in shell history) or typed by hand into an editor.
#
# This script is the middle path: YOU type the password, it never echoes, it is
# validated against the real keystore before anything is written, and it never
# reaches me or the git history.
#
# USAGE
# -----
#   powershell -ExecutionPolicy Bypass -File setup-signing.ps1
#
# Run it again any time to change the password reference.

$ErrorActionPreference = 'Stop'

$root = Split-Path -Parent $MyInvocation.MyCommand.Path
$keystore = Join-Path $root 'release.jks'
$propsFile = Join-Path $root 'keystore.properties'
$alias = 'alex'

Write-Host ''
Write-Host 'Release signing setup' -ForegroundColor Cyan
Write-Host ''

# --- Preconditions --------------------------------------------------------
if (-not (Test-Path $keystore)) {
    Write-Host "ERROR: release.jks not found in $root" -ForegroundColor Red
    Write-Host 'Create the keystore first. See keystore.properties.example.'
    exit 1
}

$keytool = (Get-Command keytool -ErrorAction SilentlyContinue).Source
if (-not $keytool) {
    Write-Host 'ERROR: keytool not found. A JDK must be on PATH.' -ForegroundColor Red
    exit 1
}

# --- Prompt, without echoing ----------------------------------------------
$secure = Read-Host "`nKeystore password (for release.jks)" -AsSecureString
$bstr = [Runtime.InteropServices.Marshal]::SecureStringToBSTR($secure)
$plain = [Runtime.InteropServices.Marshal]::PtrToStringBSTR($bstr)

if ([string]::IsNullOrWhiteSpace($plain)) {
    Write-Host 'ERROR: password cannot be blank.' -ForegroundColor Red
    exit 1
}

# --- Validate before writing ----------------------------------------------
# keytool exits non-zero and prints "password was incorrect" when wrong, so a
# bad password is caught here rather than surfacing later as a confusing Gradle
# signing failure. This matters: a keystore created after two mismatched
# password attempts uses the THIRD entry, which is easy to misremember.
Write-Host ''
Write-Host 'Checking the password against release.jks...'
$check = & $keytool -list -keystore $keystore -alias $alias -storepass $plain 2>&1
$ok = ($LASTEXITCODE -eq 0)

if (-not $ok) {
    Write-Host ''
    Write-Host 'ERROR: that password does not open release.jks.' -ForegroundColor Red
    Write-Host 'Nothing was written.'
    exit 1
}

Write-Host 'Password accepted.' -ForegroundColor Green

# --- Confirm the alias is actually in there -------------------------------
if (($check -join "`n") -notmatch [regex]::Escape($alias)) {
    Write-Host ''
    Write-Host "WARNING: alias '$alias' was not found in the keystore." -ForegroundColor Yellow
    Write-Host 'The keystore contains:'
    & $keytool -list -keystore $keystore -storepass $plain 2>&1 |
        Select-String -Pattern 'PrivateKeyEntry|trustedCertEntry' |
        ForEach-Object { '  ' + ($_ -split ',')[0].Trim() }
    $answer = Read-Host "`nUse alias '$alias' anyway? [y/N]"
    if ($answer -notmatch '^[Yy]') {
        Write-Host 'Cancelled.'
        exit 1
    }
}

# --- Write the file -------------------------------------------------------
# Written with a restrictive ACL on Windows: keystore.properties is a plain
# text password, so it should not be world-readable on a shared machine.
$content = @(
    '# Release signing configuration'
    '#'
    '# Generated by setup-signing.ps1. Git-ignored - never commit this file.'
    '# Back it up together with release.jks, or the app can never be updated.'
    ''
    "storeFile=release.jks"
    "storePassword=$plain"
    "keyAlias=$alias"
    "keyPassword=$plain"
    ''
) -join "`r`n"

Set-Content -Path $propsFile -Value $content -Encoding UTF8 -NoNewline

try {
    $acl = Get-Acl $propsFile
    # Remove inheritance, then grant only the current user.
    $acl.SetAccessRuleProtection($true, $false)
    $user = [System.Security.Principal.WindowsIdentity]::GetCurrent().Name
    $rule = New-Object System.Security.AccessControl.FileSystemAccessRule(
        $user, 'FullControl', 'Allow'
    )
    $acl.SetAccessRule($rule)
    Set-Acl -Path $propsFile -AclObject $acl
    Write-Host 'Restricted file permissions to your user account.' -ForegroundColor Green
} catch {
    Write-Host 'Note: could not tighten file permissions (not fatal).' -ForegroundColor Yellow
}

# --- Wipe the plaintext from this session ---------------------------------
$plain = $null
$bstr = [IntPtr]::Zero
[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($bstr)

Write-Host ''
Write-Host "Wrote $propsFile" -ForegroundColor Green
Write-Host ''
Write-Host 'Next:  .\build-release.bat'
Write-Host ''
Write-Host 'Keep release.jks and this password backed up somewhere safe.'
Write-Host 'Losing them means the app can never be updated - Android treats a'
Write-Host 'new signing key as a completely different app.' -ForegroundColor Yellow
Write-Host ''